package com.autoops.execution.executor;import com.autoops.files.repository.StoredFileRepository;import com.autoops.files.service.ObjectStorageService;import com.autoops.infrastructure.remote.RemoteClient;import com.autoops.workflow.entity.FileTransferStep;import org.springframework.stereotype.Component;@Component public class FileTransferStepExecutor implements StepExecutor<FileTransferStep>{private final StoredFileRepository files;private final ObjectStorageService storage;private final RemoteClient remote;public FileTransferStepExecutor(StoredFileRepository f,ObjectStorageService s,RemoteClient r){files=f;storage=s;remote=r;}public Class<FileTransferStep> supports(){return FileTransferStep.class;}public StepResult execute(FileTransferStep s,ExecutionContext c){var f=files.findById(s.storedFileId()).orElseThrow();var r=remote.upload(c.host(),c.port(),c.username(),c.password(),storage.get(f.getObjectKey()),s.destinationPath(),0);return new StepResult(r.success(),r.stdout(),r.stderr(),r.exitCode());}}
